CREATE INDEX IF NOT EXISTS idx_companies_search ON companies USING gin(to_tsvector('simple', coalesce(name,'')||' '||coalesce(email,'')));
CREATE INDEX IF NOT EXISTS idx_alerts_status ON monitoring_alerts(status,severity); CREATE INDEX IF NOT EXISTS idx_results_checked ON monitoring_check_results(check_id,checked_at DESC); CREATE INDEX IF NOT EXISTS idx_metrics_asset_collected ON monitoring_metric_samples(asset_id,collected_at DESC);
CREATE OR REPLACE VIEW global_search AS SELECT id,'company' AS entity_type,name AS title,email AS subtitle FROM companies UNION ALL SELECT id,'contact',first_name||' '||last_name,email FROM contacts UNION ALL SELECT id,'lead',title,status FROM leads UNION ALL SELECT id,'opportunity',name,stage FROM opportunities UNION ALL SELECT id,'project',name,status FROM projects UNION ALL SELECT id,'ticket',ticket_number||' - '||subject,status FROM tickets UNION ALL SELECT id,'invoice',invoice_number,status FROM invoices UNION ALL SELECT id,'monitoring_asset',name,asset_type FROM monitoring_assets;
